changeSet.sql:
DELETE FROM role_resource_operations
WHERE role_resource_id IN (
    SELECT rr.id FROM role_resources rr
    JOIN resources res ON res.id = rr.resource_id
    WHERE res.code IN ('PAYMENTS', 'CLIENT_PROFORMAS')
);

DELETE FROM role_resources
WHERE resource_id IN (
    SELECT id FROM resources WHERE code IN ('PAYMENTS', 'CLIENT_PROFORMAS')
);
